    "// Linked List: Search",
    "//",
    "// Node-by-node comparison starting from the head. Even if the list were",
    "// sorted, a binary search wouldn't be possible: there is no way to jump to",
    "// the middle without walking the pointers.",
    "#include <cstdio>",
    "#include <string>",
    "",
    "static int comparisons = 0;",
    "",
    "struct Node {",
    "    int data;",
    "    Node* next;",
    "};",
    "",
    "Node* createNode(int value) {",
    "    Node* newNode = new Node;",
    "    newNode->data = value;",
    "    newNode->next = nullptr;",
    "    return newNode;",
    "}",
    "",
    "int search(Node* head, int key) {",
    "    Node* current = head;",
    "    int position = 0;",
    "",
    "    while (current != nullptr) {",
    "",
    "        if (current->data == key) {",
    "            return position;",
    "        }",
    "",
    "        current = current->next;",
    "        position++;",
    "    }",
    "",
    "    return -1;",
    "}",
    "",
    "static Node* buildList(const int* values, int n) {",
    "    Node* head = nullptr;",
    "    Node* tail = nullptr;",
    "    for (int i = 0; i < n; i++) {",
    "        Node* node = createNode(values[i]);",
    "        if (!head) { head = tail = node; }",
    "        else { tail->next = node; tail = node; }",
    "    }",
    "    return head;",
    "}",
    "",
    "static void freeList(Node* head) {",
    "    while (head) { Node* next = head->next; delete head; head = next; }",
    "}",
    "",
    "int main() {",
    "",
    "    const int values[] = {10, 20, 30, 40, 50};",
    "    struct Case { const char* label; int key; };",
    "    const Case cases[] = {",
    "        {\"key at the head (10)\", 10},",
    "        {\"key in the middle (30)\", 30},",
    "        {\"key at the tail (50)\", 50},",
    "        {\"key absent (35)\", 35},",
    "    };",
    "",
    "    for (const Case& c : cases) {",
    "        trace::resetNodeIds();",
    "        Node* head = buildList(values, 5);",
    "        comparisons = 0;",
    "",
    "        search(head, c.key);",
    "        freeList(head);",
    "    }",
    "",
    "    return 0;",
    "}"
